const defaultState = {
  settings:structuredClone(DEFAULT_SETTINGS), products:structuredClone(DEFAULT_PRODUCTS), cart:[], wishlist:[],
  profile:{name:'',email:'',phone:'',address:'',city:'',state:'',pincode:'',landmark:'',phoneVerified:false,emailVerified:false,authUserId:'',googleConnected:false}, orders:[], searches:{}, reviews:[]
};

function mergeDeep(base, incoming){
  if(Array.isArray(base)) return Array.isArray(incoming) ? incoming : structuredClone(base);
  if(base && typeof base==='object'){
    const out={...base};
    for(const [k,v] of Object.entries(incoming||{})) out[k]=mergeDeep(base[k],v);
    return out;
  }
  return incoming===undefined?base:incoming;
}
function loadState(){try{return mergeDeep(defaultState,JSON.parse(localStorage.getItem(KEY)||'null')||{})}catch{return structuredClone(defaultState)}}
let state=loadState();
let activeOfferTimer=null;

function normalizeProduct(p){
  p.sizes=Object.assign({S:false,M:false,L:false,XL:false,XXL:false},p.sizes||{});
  const raw=Array.isArray(p.colors)?p.colors:[];
  p.colors=raw.map(c=>typeof c==='string'?{name:c,hex:COLOR_LIBRARY[c]||'#9aa0a8',enabled:true}:Object.assign({name:'Custom',hex:'#999999',enabled:true},c));
  if(!p.colors.length)p.colors=[{name:'Black',hex:'#111214',enabled:true}];
  p.images=Array.isArray(p.images)&&p.images.length?p.images:[IMG.hero];
  p.features=Array.isArray(p.features)?p.features:[];
  return p;
}
state.products=state.products.map(normalizeProduct);
state.settings=mergeDeep(DEFAULT_SETTINGS,state.settings||{});
state.settings.payments=Object.assign({},DEFAULT_SETTINGS.payments,state.settings.payments||{});
state.settings.codAdvancePercent=Number.isFinite(Number(state.settings.codAdvancePercent))?Number(state.settings.codAdvancePercent):20;
state.settings.upiAdvancePercent=Number.isFinite(Number(state.settings.upiAdvancePercent))?Number(state.settings.upiAdvancePercent):20;
state.settings.collections=Array.isArray(state.settings.collections)&&state.settings.collections.length?state.settings.collections:structuredClone(DEFAULT_SETTINGS.collections);
state.settings.textOverrides=state.settings.textOverrides&&typeof state.settings.textOverrides==='object'?state.settings.textOverrides:{};
state.settings.content=Object.assign({},DEFAULT_SETTINGS.content,state.settings.content||{});
state.settings.cashfree=Object.assign({},DEFAULT_SETTINGS.cashfree,state.settings.cashfree||{});
state.settings.auth=Object.assign({},DEFAULT_SETTINGS.auth,state.settings.auth||{});
state.settings.offer=Object.assign({},DEFAULT_SETTINGS.offer,state.settings.offer||{});
state.settings.theme=Object.assign({},DEFAULT_SETTINGS.theme,state.settings.theme||{});
state.orders=(state.orders||[]).map(ensureOrderTracking);
save();

function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function money(n){return `${state.settings.currency||'₹'}${Number(n||0).toLocaleString('en-IN')}`}
function toast(msg){const el=document.getElementById('toast');if(!el)return;el.textContent=msg;el.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>el.classList.remove('show'),2500)}
function product(id){return state.products.find(p=>p.id===id)}
function totalItems(){return state.cart.reduce((a,x)=>a+Number(x.qty||0),0)}
function cartSubtotal(){return state.cart.reduce((a,x)=>a+(product(x.id)?.price||0)*Number(x.qty||0),0)}
function shipping(){return Number(state.settings.shipping||0)}
function cartTotal(discount=0){return Math.max(0,cartSubtotal()+shipping()-discount)}
function profileReadyForCheckout(){const p=state.profile;return Boolean(p.emailVerified&&String(p.name||'').trim()&&String(p.phone||'').trim()&&String(p.address||'').trim()&&String(p.landmark||'').trim()&&String(p.city||'').trim()&&String(p.state||'').trim()&&/^\d{6}$/.test(String(p.pincode||'')))}
function ensureOrderTracking(o){
  o=o||{};o.status=o.status||'Placed';o.createdAt=o.createdAt||new Date().toISOString();
  o.expectedDeliveryDate=o.expectedDeliveryDate||addDaysISO(o.createdAt,5);o.deliveryWindow=o.deliveryWindow||'10 AM – 9 PM';
  o.trackingNumber=o.trackingNumber||'';o.courier=o.courier||'';o.customerNote=o.customerNote||'';o.lastUpdatedAt=o.lastUpdatedAt||o.createdAt;
  o.timeline=Array.isArray(o.timeline)?o.timeline:[];if(!o.timeline.some(x=>x.status==='Placed'))o.timeline.unshift({status:'Placed',at:o.createdAt,note:'Order received'});
  o.paymentStatus=o.paymentStatus||'pending';o.advancePaid=Number(o.advancePaid||0);o.remainingDue=Number(o.remainingDue??Math.max(0,Number(o.total||0)-o.advancePaid));
  return o;
}
function addDaysISO(base,days){const d=new Date(base||Date.now());d.setDate(d.getDate()+days);return d.toISOString()}
function fmtDate(v){try{return new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v))}catch{return '—'}}
function fmtDay(v){try{return new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(v))}catch{return '—'}}
function statusClass(s){return String(s||'Placed').toLowerCase().replace(/\s+/g,'-')}
function activeOffer(){
  const o=state.settings.offer||{};if(!o.enabled)return false;
  const now=Date.now(),start=o.startAt?new Date(o.startAt).getTime():0,end=o.endAt?new Date(o.endAt).getTime():Infinity;
  return now>=start&&now<end;
}
function offerRemaining(){const end=state.settings.offer?.endAt?new Date(state.settings.offer.endAt).getTime():0;return Math.max(0,end-Date.now())}
function fmtTimer(ms){const total=Math.max(0,Math.floor(ms/1000)),d=Math.floor(total/86400),h=Math.floor((total%86400)/3600),m=Math.floor((total%3600)/60),s=total%60;return `${d?d+'d ':''}${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}

function supabaseHeaders(extra={}){return Object.assign({'apikey':SUPABASE_PUBLISHABLE_KEY,'Authorization':`Bearer ${SUPABASE_PUBLISHABLE_KEY}`,'Content-Type':'application/json'},extra)}
async function supabaseRequest(url=SUPABASE_REST,options={}){const res=await fetch(url,{...options,headers:supabaseHeaders(options.headers||{})});const text=await res.text();let data=null;try{data=text?JSON.parse(text):null}catch{}if(!res.ok)throw new Error(data?.message||data?.error_description||text||`HTTP ${res.status}`);return data}

async function saveOrderToSupabase(order){
  try{
    const dbId=Date.now();
    order.cloudRowId=order.cloudRowId||dbId;
    const row={id:Number(order.cloudRowId),'Customer name':order.customer?.name||'','Customer address':`${order.customer?.address||''}, ${order.customer?.city||''}, ${order.customer?.state||''}, ${order.customer?.pincode||''}`,'Product name':JSON.stringify(order),'Customer number':order.customer?.phone||'','Product price':String(order.total??0),'Product size':(order.items||[]).map(x=>`${x.name||x.id||product(x.id)?.name||''} x${x.qty||1} ${x.size||''} ${x.color||''}`).join(' | ')};
    await supabaseRequest(order.cloudRowId===dbId?SUPABASE_REST:`${SUPABASE_REST}?id=eq.${encodeURIComponent(order.cloudRowId)}`,{method:order.cloudRowId===dbId?'POST':'PATCH',headers:{'Prefer':'return=minimal'},body:JSON.stringify(row)});return true;
  }catch(e){console.error(e);toast(`Cloud order save failed: ${e.message||'Supabase error'}`);return false}
}
async function loadCloudOrderById(id){try{const data=await supabaseRequest(`${SUPABASE_REST}?select=*&order=id.desc`);for(const row of (data||[])){let o=null;try{o=JSON.parse(row['Product name'])}catch{}if(o?.id===id){o.cloudRowId=row.id;return ensureOrderTracking(o)}}}catch{}return null}

function applyLocalOrder(order){state.orders.unshift(ensureOrderTracking(order));state.profile=mergeDeep(state.profile,order.customer||{});state.cart=[];save()}
async function finalizeOrder(order,{localOnly=false}={}){const cloudSaved=localOnly?true:await saveOrderToSupabase(order);if(!cloudSaved)return false;applyLocalOrder(order);render();showSuccess(order);return true}
function showSuccess(order){location.href=`tracking.html?order=${encodeURIComponent(order.id)}`}

function logo(){return `<a class="logo" href="index.html" aria-label="${esc(state.settings.brand)} home"><span class="logo-frame"><img class="logo-image" src="${LOGO_SRC}" alt="${esc(state.settings.brand)} logo"></span><span class="logo-text">${esc(state.settings.brand)}<small>${esc(state.settings.tagline)}</small></span></a>`}
function offerStrip(){if(!activeOffer())return '';clearInterval(activeOfferTimer);const o=state.settings.offer;const end=o.endAt?new Date(o.endAt).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'Limited time';const id='offerCount';activeOfferTimer=setInterval(()=>{const el=document.getElementById(id);if(!el){clearInterval(activeOfferTimer);return}el.textContent=fmtTimer(offerRemaining());if(offerRemaining()<=0){clearInterval(activeOfferTimer);render()}},1000);return `<div class="offer-strip"><div class="container offer-inner"><div><b>${esc(o.headline)}</b><span>${esc(o.text)}</span></div><div class="offer-code"><span>CODE: <strong>${esc(o.coupon||'—')}</strong></span><em id="${id}">${fmtTimer(offerRemaining())}</em><small>Ends ${esc(end)}</small></div></div></div>`}
function iconSvg(type){const icons={user:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 21a8 8 0 0 0-16 0M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Z"/></svg>`,heart:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 8.6c0 5.3-8.8 10.1-8.8 10.1S3.2 13.9 3.2 8.6A4.6 4.6 0 0 1 12 6.1a4.6 4.6 0 0 1 8.8 2.5Z"/></svg>`,bag:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6.5 8.5h11l1 12h-13l1-12Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/></svg>`,menu:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h16"/></svg>`};return icons[type]||''}
function header(){return `${offerStrip()}<header class="header"><div class="container nav"><a class="mobile-menu" aria-label="Open menu" href="categories.html?view=menu">${iconSvg('menu')}</a>${logo()}<nav id="nav" class="nav-links"><a href="index.html">Home</a><a href="shop.html">Shop</a><a href="categories.html">Categories</a><a href="wishlist.html">Wishlist</a><a href="tracking.html">Track Order</a><a href="help-care.html">Help & Care</a></nav><div class="search-wrap"><input id="topSearch" class="search" placeholder="Search products, category or barcode…" onkeydown="if(event.key==='Enter'){event.preventDefault();const q=this.value.trim();if(q)location.href='search.html?q='+encodeURIComponent(q)}"><span class="search-icon">⌕</span><button type="button" class="scan-btn" title="Scan barcode" aria-label="Scan barcode" onclick="startBarcodeScan()">▥</button></div><div class="nav-actions"><a class="icon-btn profile-action" href="customer-details.html" title="Customer details" aria-label="Customer details">${iconSvg('user')}<span class="action-label">Details</span></a><a class="icon-btn wishlist-action" href="wishlist.html" title="Wishlist" aria-label="Wishlist">${iconSvg('heart')}<span class="badge">${state.wishlist.length||''}</span><span class="action-label">Wishlist</span></a><a class="icon-btn" href="bag.html" title="Shopping bag" aria-label="Shopping bag">${iconSvg('bag')}<span class="badge">${totalItems()||''}</span><span class="action-label">Bag</span></a></div></div></header>`}
function hero(){const c=state.settings.content||{};return `<section class="hero"><div class="hero-media"><img src="${esc(state.settings.heroImage||IMG.hero)}" alt="Kryven Era collection"><div class="hero-fade"></div>${state.settings.heroVideo?`<video autoplay muted loop playsinline src="${esc(state.settings.heroVideo)}"></video>`:''}</div><div class="container hero-grid"><div class="hero-copy"><div class="kicker">${esc(c.heroKicker||'KRYVEN ERA · PREMIUM STREETWEAR')}</div><h1>${esc(state.settings.heroTitle)}</h1><p>${esc(state.settings.heroText)}</p><div class="hero-cta"><a class="btn primary" href="shop.html">${esc(c.heroPrimaryCta||'Explore Collection →')}</a><a class="btn ghost" href="categories.html?category=T-Shirts">${esc(c.heroSecondaryCta||'Shop the Drop')}</a></div><div class="hero-highlights"><span>${esc(c.heroHighlight1||'SIZE-AWARE STOCK')}</span><span>${esc(c.heroHighlight2||'TRACKED DELIVERY')}</span><span>${esc(c.heroHighlight3||'PREMIUM FINISH')}</span></div></div><div class="hero-badge"><span>${esc(c.heroBadge||'NEW DROP')}</span><b>${esc(c.heroBadgeNumber||'26')}</b><small>${esc(c.heroBadgeSub||'Limited edits')}</small></div></div></section>`}
function categories(){const cats=(state.settings.collections||[]).filter(c=>c&&c.enabled!==false);return `<section class="section"><div class="container"><div class="section-head"><div><div class="eyebrow">01 / COLLECTIONS</div><h2>The Era, Your Way.</h2></div><p class="muted">Clean silhouettes, metallic details and everyday streetwear.</p></div><div class="categories">${cats.map((c,i)=>{const name=typeof c==='string'?c:c.name;const p=state.products.find(x=>x.category===name)||state.products.find(x=>x.images?.length);const img=(typeof c==='string'?null:c.image)||p?.images?.[0]||IMG.hero;return `<a class="cat" href="categories.html?category=${encodeURIComponent(name)}"><img src="${esc(img)}" alt="${esc(name)}"><span class="cat-index">${String(i+1).padStart(2,'0')}</span><div class="cat-shade"></div><div class="cat-info"><b>${esc(name)}</b><span>${state.products.filter(x=>x.category===name).length} pieces →</span></div></a>`}).join('')}</div></div></section>`}
function colorMeta(c){const o=typeof c==='string'?{name:c,hex:COLOR_LIBRARY[c]||'#9ca3aa',enabled:true}:c;return o}
function colorSwatches(p,small=false){const arr=(p.colors||[]).map(colorMeta).filter(x=>x.enabled!==false);return arr.length?`<div class="swatch-row">${arr.slice(0,5).map(c=>`<span class="swatch ${small?'small':''}" title="${esc(c.name)}" style="--swatch:${esc(c.hex)}"></span>`).join('')}</div>`:''}
function productCard(p){const wished=state.wishlist.includes(p.id);const href=`product.html?id=${encodeURIComponent(p.id)}`;return `<article class="card"><a class="card-link" href="${href}" aria-label="View ${esc(p.name)}"><div class="card-media"><img src="${esc(p.images?.[0]||IMG.hero)}" alt="${esc(p.name)}" loading="lazy"><span class="pill">${esc(p.offerText||p.discount||'LIMITED')}</span><span class="quick-label">VIEW PRODUCT</span></div><div class="card-body"><div class="eyebrow">${esc(p.category)} · ${esc(p.id)}</div><h3>${esc(p.name)}</h3><div class="meta">★ ${p.rating||5} · ${p.reviews||0} reviews</div><div class="price-row"><b class="price">${money(p.price)}</b><span class="mrp">${money(p.mrp)}</span><span class="discount">${esc(p.discount||'')}</span></div>${p.offerUntil&&new Date(p.offerUntil).getTime()>Date.now()?`<div class="mini-offer">Offer ends ${esc(fmtDay(p.offerUntil))}</div>`:''}<div class="card-foot"><div class="size-row">${Object.entries(p.sizes||{}).map(([sz,on])=>`<span class="size ${on?'':'off'}">${sz}</span>`).join('')}</div>${colorSwatches(p,true)}</div></div></a><button type="button" class="like ${wished?'active':''}" aria-label="${wished?'Remove from wishlist':'Add to wishlist'}" onclick="event.preventDefault();event.stopPropagation();toggleWishlist('${esc(p.id)}')">${wished?'♥':'♡'}</button></article>`}
function shop(){const c=state.settings.content||{},cats=(state.settings.collections||[]).filter(x=>x&&x.enabled!==false);return `<section class="section section-tight"><div class="container"><div class="drop-head"><div><div class="eyebrow">${esc(c.shopEyebrow||'02 / THE DROP')}</div><h2>${esc(c.shopTitle||'Featured Products.')}</h2></div><div class="chips"><a class="chip gold" href="shop.html">View all</a>${cats.map(x=>`<a class="chip" href="categories.html?category=${encodeURIComponent(typeof x==='string'?x:x.name)}">${esc(typeof x==='string'?x:x.name)}</a>`).join('')}</div></div><div class="drop-ribbon"><span>${esc(c.shopRibbon||'LIMITED EDIT')}</span><b>${esc(state.settings.deliveryNote)}</b><span>CODE ${esc(state.settings.offer?.coupon||'KRYVEN10')}</span></div><div class="product-grid">${state.products.map(productCard).join('')}</div></div></section>`}
function trust(){const c=state.settings.content||{};return `<section class="section section-tight"><div class="container trust-grid"><div class="trust-card"><b>${esc(c.trust1||'Premium Fabric')}</b><span>Heavyweight, soft and made for daily wear.</span></div><div class="trust-card"><b>${esc(c.trust2||'Flexible Payment')}</b><span>${esc(state.settings.codAdvancePercent||20)}% now + ${100-Number(state.settings.codAdvancePercent||20)}% after delivery, UPI and cards.</span></div><div class="trust-card"><b>${esc(c.trust3||'Size Controls')}</b><span>Admin can enable or disable each size and colour.</span></div><div class="trust-card"><b>${esc(c.trust4||'Tracked Delivery')}</b><span>Live order status, ETA, courier and tracking number.</span></div></div></section>`}
function footer(){const c=state.settings.content||{};return `<footer class="footer"><div class="container footer-grid"><div><div>${logo()}</div><p class="muted">${esc(c.footerAbout||'A refined storefront system with an owner-controlled catalogue, offers, stock, sizes, colours and payment settings.')}</p></div><div><b>${esc(c.footerShopTitle||'SHOP')}</b><a href="shop.html">All products</a><a href="categories.html">Categories</a><a href="wishlist.html">Wishlist</a></div><div><b>${esc(c.footerOrderTitle||'ORDER')}</b><a href="checkout.html">Checkout</a><a href="tracking.html">Track order</a><a href="customer-details.html">Customer details</a></div><div><b>${esc(c.footerSupportTitle||'SUPPORT')}</b><a href="help-care.html">Help & Care</a><a href="reviews.html">Reviews</a><a href="admin.html">Admin Panel</a><a target="_blank" rel="noopener" href="https://wa.me/${esc(state.settings.whatsapp)}">WhatsApp</a></div></div><div class="container footer-note">${esc(c.footerNote||`© 2026 ${state.settings.brand} · Premium Streetwear Edition`)}</div></footer>`}
function pageShell(title,content){return `${header()}<main class="page-main container"><div class="page-title"><div class="eyebrow">KRYVEN ERA</div><h1>${esc(title)}</h1></div>${content}</main>${footer()}${drawDrawer()}${drawModal()}`}
function drawDrawer(){return `<div id="drawer" class="drawer" aria-hidden="true"><div class="drawer-panel" id="drawerPanel"></div></div>`}
function drawModal(){return `<div id="modal" class="modal" aria-hidden="true"><div class="modal-card" id="modalCard"></div></div>`}
function lockOverlayScroll(){document.documentElement.classList.add('overlay-open');document.body.classList.add('overlay-open')}
function unlockOverlayScroll(){document.documentElement.classList.remove('overlay-open');document.body.classList.remove('overlay-open')}
function openDrawer(content){const d=document.getElementById('drawer');if(!d)return;const panel=document.getElementById('drawerPanel');panel.innerHTML=content;d.classList.add('show');d.setAttribute('aria-hidden','false');lockOverlayScroll();d.onclick=e=>{if(e.target===d)closeDrawer()};panel.onclick=e=>e.stopPropagation()}
function closeDrawer(){const d=document.getElementById('drawer');if(!d)return;d.classList.remove('show');d.setAttribute('aria-hidden','true');unlockOverlayScroll()}
function openModal(content){const m=document.getElementById('modal');if(!m)return;const card=document.getElementById('modalCard');card.innerHTML=content;m.classList.add('show');m.setAttribute('aria-hidden','false');lockOverlayScroll();m.onclick=e=>{if(e.target===m)closeModal()};card.onclick=e=>e.stopPropagation()}
function closeModal(){const m=document.getElementById('modal');if(!m)return;m.classList.remove('show');m.setAttribute('aria-hidden','true');unlockOverlayScroll()}

function openCategory(cat){location.href=`categories.html?category=${encodeURIComponent(cat)}`}
function openProduct(id){if(id)location.href=`product.html?id=${encodeURIComponent(id)}`}
function setMainImage(i,id){const p=product(id);const img=document.getElementById('mainProductImage');if(!p||!img)return;img.src=p.images[i];document.querySelectorAll('.thumb').forEach((x,n)=>x.classList.toggle('active',n===i))}
function selectProductSize(size){if(!window.__selected)return;window.__selected.size=size;document.querySelectorAll('#sizeOptions .opt').forEach(b=>b.classList.toggle('selected',b.textContent.trim().startsWith(size)))}
function selectProductColor(name){if(!window.__selected)return;window.__selected.color=name;document.querySelectorAll('#colorOptions .color-option').forEach(b=>b.classList.toggle('selected',b.textContent.trim()===name));toast(`${name} selected`)}
function addToBag(id,size,color='Black'){const p=product(id);if(!p)return;if(!size||!p.sizes[size]){toast('Please choose an available size');return}const c=colorMeta((p.colors||[]).find(x=>colorMeta(x).name===color));if(c.enabled===false){toast('That colour is disabled');return}const line=state.cart.find(x=>x.id===id&&x.size===size&&x.color===color);if(line)line.qty++;else state.cart.push({id,size,color,qty:1,name:p.name,image:p.images?.[0]||''});save();toast('✓ Added to bag');render()}
function toggleWishlist(id){state.wishlist=state.wishlist.includes(id)?state.wishlist.filter(x=>x!==id):[...state.wishlist,id];save();toast(state.wishlist.includes(id)?'Added to wishlist':'Removed from wishlist');render()}
function changeQty(i,d){const row=state.cart[i];if(!row)return;row.qty=Math.max(0,row.qty+d);if(row.qty===0)state.cart.splice(i,1);save();render()}
function openBag(){location.href='bag.html'}
function openProfile(){location.href='customer-details.html'}
function collectProfileFrom(prefix='pf'){const p={name:document.getElementById(`${prefix}Name`).value.trim(),phone:document.getElementById(`${prefix}Phone`).value.trim(),email:document.getElementById(`${prefix}Email`).value.trim(),city:document.getElementById(`${prefix}City`).value.trim(),state:document.getElementById(`${prefix}State`).value.trim(),pincode:document.getElementById(`${prefix}Pin`).value.trim(),address:document.getElementById(`${prefix}Address`).value.trim(),landmark:document.getElementById(`${prefix}Landmark`)?.value.trim()||''};return p}
function saveProfile(){const next=collectProfileFrom();if(!next.name||!next.phone||!next.address||!next.city||!next.state||!next.landmark||!/^[0-9]{6}$/.test(next.pincode)){toast('Fill all required customer details');return}if(next.phone.replace(/\D/g,'').length<10){toast('Enter a valid phone number');return}if(next.email&&!/^\S+@\S+\.\S+$/.test(next.email)){toast('Check the email address');return}state.profile=next;save();localStorage.setItem(PROFILE_SEEN_KEY,'1');location.href='checkout.html'}
function search(q){q=q.trim().toLowerCase();if(!q)return;state.searches[q]=(state.searches[q]||0)+1;save();location.href=`search.html?q=${encodeURIComponent(q)}`}
function renderSearchOverlay(){return false}
function openMobileMenu(){location.href='categories.html?view=menu'}
function openWishlist(){location.href='wishlist.html'}
function openSupport(){location.href='help-care.html'}
function openTracking(){location.href='tracking.html'}
async function trackOrder(){const id=document.getElementById('trackId')?.value.trim(),phone=document.getElementById('trackPhone')?.value.trim()||'';if(!id)return toast('Enter your order ID');let o=state.orders.find(x=>x.id===id)||await loadCloudOrderById(id);if(o&&phone&&o.customer?.phone!==phone)o=null;document.getElementById('trackResult').innerHTML=o?trackingCard(o):'<div class="empty-state small">Order not found.</div>'}
function trackingCard(o){ensureOrderTracking(o);return `<div class="tracking-card"><div class="summary-row"><span>${esc(o.id)}</span><span class="status ${statusClass(o.status)}">${esc(o.status)}</span></div><p class="muted">${esc(o.customer?.name||'Customer')} · ${fmtDate(o.createdAt)}</p><div class="eta-box"><span>EXPECTED DELIVERY</span><b>${fmtDay(o.expectedDeliveryDate)}</b><small>${esc(o.deliveryWindow)}</small></div><div class="timeline">${STATUS_FLOW.map((s,i)=>{const e=o.timeline.find(x=>x.status===s);return `<div class="timeline-item ${e?'done':''} ${o.status===s?'current':''}"><span>${e?'✓':String(i+1).padStart(2,'0')}</span><div><b>${s}</b><small>${e?fmtDate(e.at):'Pending'}</small><em>${e?esc(e.note||STATUS_COPY[s]||s):'Not reached yet'}</em></div></div>`}).join('')}</div></div>`}

function openCheckout(){if(!state.cart.length){toast('Add at least one product before checkout');return}if(location.pathname.endsWith('checkout.html')){render();return}location.href='checkout.html'}
function discountAmount(sub,code){const o=state.settings.offer;if(code&&activeOffer()&&code.toUpperCase()===(o.coupon||'').toUpperCase())return Math.round(sub*.10);return code==='KRYVEN10'?Math.round(sub*.10):0}
function checkoutMarkup(){if(!state.cart.length)return '<div class="empty-state"><h2>Your bag is empty.</h2><a class="btn primary" href="shop.html">Explore Collection →</a></div>';const sub=cartSubtotal(),p=state.settings.payments,cpf=Number(state.settings.codAdvancePercent||20),upf=Number(state.settings.upiAdvancePercent||20);return `<form id="checkoutForm" class="checkout-grid" onsubmit="event.preventDefault();placeOrder()" novalidate><div><div class="checkout-card"><div class="panel-title"><div><div class="eyebrow">01 / DELIVERY</div><h3>Shipping details</h3></div><span class="chip gold">Saved details auto-fill</span></div><div class="form-grid"><div class="field"><label>NAME *</label><input id="coName" value="${esc(state.profile.name)}" required></div><div class="field"><label>PHONE *</label><input id="coPhone" value="${esc(state.profile.phone)}" inputmode="tel" required minlength="10" ></div><div class="field"><label>EMAIL *</label><input id="coEmail" value="${esc(state.profile.email)}" type="email" required readonly></div><div class="field"><label>CITY *</label><input id="coCity" value="${esc(state.profile.city)}" required></div><div class="field"><label>STATE *</label><input id="coState" value="${esc(state.profile.state)}" required></div><div class="field"><label>PINCODE *</label><input id="coPin" value="${esc(state.profile.pincode)}" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required></div><div class="field full-span"><label>FULL ADDRESS *</label><textarea id="coAddress" required>${esc(state.profile.address)}</textarea></div><div class="field full-span"><label>LANDMARK *</label><input id="coLandmark" value="${esc(state.profile.landmark||'')}" required></div></div></div><div class="checkout-card"><div class="panel-title"><div><div class="eyebrow">02 / OFFER</div><h3>Apply a discount</h3></div></div><div class="coupon-row"><input id="coupon" placeholder="Enter coupon" value=""><button type="button" class="btn" onclick="applyCheckoutCoupon()">Apply</button></div><div id="couponMsg" class="muted"></div></div><div class="checkout-card"><div class="panel-title"><div><div class="eyebrow">03 / PAYMENT</div><h3>Choose payment</h3></div></div><div class="payment-choice-list">${p.cod?`<label class="payment-choice"><input name="pay" type="radio" value="cod" checked><span><b>Cash on Delivery</b><small>${cpf}% now via Cashfree · ${100-cpf}% after delivery</small></span><strong>${cpf}% + ${100-cpf}%</strong></label>`:''}${p.upi?`<label class="payment-choice"><input name="pay" type="radio" value="upi" ${p.cod?'':'checked'}><span><b>UPI Payment</b><small>${upf}% now via Cashfree · ${100-upf}% after delivery</small></span><strong>${upf}% + ${100-upf}%</strong></label>`:''}${p.card?`<label class="payment-choice"><input name="pay" type="radio" value="card" ${p.cod||p.upi?'':'checked'}><span><b>Credit / Debit Card</b><small>${state.settings.cashfree.enabled?'Cashfree checkout':'Cashfree connection required'}</small></span><strong>100%</strong></label>`:''}</div><div class="payment-note">${state.settings.cashfree.enabled?'Required payment is verified by Cashfree before the order is confirmed or shown in Admin.':'Cashfree must be enabled and verified before any order can be confirmed.'}</div></div></div><aside class="summary-card checkout-summary"><div class="eyebrow">04 / ORDER SUMMARY</div><h3>Ready to place.</h3><div class="summary-row"><span>Subtotal</span><b>${money(sub)}</b></div><div class="summary-row"><span>Shipping</span><b>${money(shipping())}</b></div><div class="summary-row"><span>Discount</span><b id="discountLine">—</b></div><div class="summary-row total"><span>Total</span><b id="sumTotal">${money(sub+shipping())}</b></div><div class="offer-note">${activeOffer()?`Offer live · use <strong>${esc(state.settings.offer.coupon||'KRYVEN10')}</strong>`:'Offer currently inactive'}</div><button type="submit" class="btn primary full">Place Order Securely →</button><p class="tiny muted">Email verification is required. Phone number is required for delivery contact. The order is not created in Admin until Cashfree confirms the required payment.</p></aside></form>`}
function saveCheckoutProfile(){state.profile={...state.profile,name:document.getElementById('coName')?.value.trim()||'',phone:document.getElementById('coPhone')?.value.trim()||'',email:document.getElementById('coEmail')?.value.trim()||'',city:document.getElementById('coCity')?.value.trim()||'',state:document.getElementById('coState')?.value.trim()||'',pincode:document.getElementById('coPin')?.value.trim()||'',address:document.getElementById('coAddress')?.value.trim()||'',landmark:document.getElementById('coLandmark')?.value.trim()||''};save()}
function applyCheckoutCoupon(){const code=(document.getElementById('coupon')?.value||'').trim().toUpperCase(),amt=discountAmount(cartSubtotal(),code);document.getElementById('couponMsg').textContent=amt?`Applied ${code} · you save ${money(amt)}`:'Coupon not valid or offer expired';const el=document.getElementById('discountLine');const total=document.getElementById('sumTotal');if(el)el.textContent=amt?`−${money(amt)}`:'—';if(total)total.textContent=money(cartTotal(amt));window.__checkoutDiscount=amt;window.__checkoutCoupon=code}
function buildOrder(payment,discount=0){const createdAt=new Date().toISOString(),total=cartTotal(discount),id=`KE-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`,pct=payment==='cod'?Number(state.settings.codAdvancePercent||20):payment==='upi'?Number(state.settings.upiAdvancePercent||20):100,advance=payment==='card'?total:Math.round(total*pct/100);return ensureOrderTracking({id,createdAt,status:'Placed',customer:structuredClone(state.profile),items:state.cart.map(x=>{const pr=product(x.id);return {id:x.id,name:pr?.name||x.id,size:x.size,color:x.color,qty:x.qty,image:pr?.images?.[0]||''}}),subtotal:cartSubtotal(),discount,total,payment,advanceRequired:advance,advancePaid:0,remainingDue:Math.max(0,total-advance),paymentStatus:payment==='card'?'gateway_pending':'advance_pending',referralSource:localStorage.getItem('kryven-era-referral-source')||'',offerCode:window.__checkoutCoupon||''})}
async function validateCheckout(){if(!state.cart.length){toast('Add a product first');return false}saveCheckoutProfile();const ids=['coName','coPhone','coCity','coState','coPin','coAddress','coLandmark','coEmail'];const rules={coName:[v=>!!v.trim(),'Enter your name'],coPhone:[v=>validPhone(v),'Enter a valid 10-digit phone number'],coCity:[v=>!!v.trim(),'Enter your city'],coState:[v=>!!v.trim(),'Enter your state'],coPin:[v=>/^\d{6}$/.test(v.trim()),'Enter a valid 6-digit pincode'],coAddress:[v=>!!v.trim(),'Enter your full address'],coLandmark:[v=>!!v.trim(),'Enter a landmark'],coEmail:[v=>/^\S+@\S+\.\S+$/.test(v.trim()),'Enter your verified email address']};let ok=true;for(const id of ids){const [fn,msg]=rules[id];if(!validateInputValue(id,fn,msg))ok=false}if(!ok){toast('Fix the red fields before continuing');return false}const user=await getCurrentAuthUser();if(!user?.email||!state.profile.emailVerified){toast('Verify your email before placing an order.');location.href='customer-details.html?return=checkout';return false}return profileReadyForCheckout()}
async function placeOrder(){if(window.__orderSubmitting)return;window.__orderSubmitting=true;try{if(!(await validateCheckout()))return;const payment=document.querySelector('input[name="pay"]:checked')?.value;if(!payment){toast('Select a payment method');return}const order=buildOrder(payment,window.__checkoutDiscount||0);if(payment==='cod'){order.advanceRequired=Math.round(order.total*(Number(state.settings.codAdvancePercent||20)/100));order.remainingDue=Math.max(0,order.total-order.advanceRequired)}else if(payment==='upi'){order.advanceRequired=Math.round(order.total*(Number(state.settings.upiAdvancePercent||20)/100));order.remainingDue=Math.max(0,order.total-order.advanceRequired)}else{order.advanceRequired=order.total;order.remainingDue=0}await startCashfree(order)}finally{window.__orderSubmitting=false}}
async function handleCodOrder(order){order.advanceRequired=Math.round(order.total*(Number(state.settings.codAdvancePercent||20)/100));order.remainingDue=Math.max(0,order.total-order.advanceRequired);return startCashfree(order)}
function savePendingPayment(order){sessionStorage.setItem('kryven-pending-payment-order',JSON.stringify(order));sessionStorage.setItem('kryven-pending-payment-at',String(Date.now()))}
function readPendingPayment(orderId){try{const raw=sessionStorage.getItem('kryven-pending-payment-order');if(!raw)return null;const o=JSON.parse(raw);return o?.id===orderId?ensureOrderTracking(o):null}catch{return null}}
function clearPendingPayment(){sessionStorage.removeItem('kryven-pending-payment-order');sessionStorage.removeItem('kryven-pending-payment-at')}
function makeUpiLink(order,amount){const upi=encodeURIComponent(state.settings.upi||'kryvenera@upi'),name=encodeURIComponent(state.settings.brand||'Kryven Era');return `upi://pay?pa=${upi}&pn=${name}&am=${Number(amount||0).toFixed(2)}&cu=INR&tn=${encodeURIComponent('Kryven Era '+order.id)}`}
async function markPaymentVerificationPending(id){toast('This order will appear only after Cashfree confirms the required payment.');return false}
async function startUPI(order){order.advanceRequired=Math.round(order.total*(Number(state.settings.upiAdvancePercent||20)/100));order.remainingDue=Math.max(0,order.total-order.advanceRequired);return startCashfree(order)}
async function loadCashfreeScript(){if(window.Cashfree)return window.Cashfree;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://sdk.cashfree.com/js/v3/cashfree.js';s.onload=resolve;s.onerror=reject;document.head.appendChild(s)});return window.Cashfree}
async function startCashfree(order){const cf=state.settings.cashfree||{};if(!cf.enabled){toast('Enable Cashfree in Admin → Payments before placing an order.');return false}if(!cf.checkoutEndpoint||!cf.verifyEndpoint){toast('Cashfree create-order and verify endpoints are required.');return false}savePendingPayment(order);try{const res=await fetch(cf.checkoutEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({orderId:order.id,amount:paymentAmount(order),currency:'INR',customer:order.customer,items:order.items,returnUrl:location.origin+location.pathname+'?payment_return=1&order_id='+encodeURIComponent(order.id)})});if(!res.ok)throw new Error(await res.text());const data=await res.json();if(!data.paymentSessionId)throw new Error('No paymentSessionId returned by backend');const Cashfree=await loadCashfreeScript();const cashfree=Cashfree({mode:cf.mode==='production'?'production':'sandbox'});await cashfree.checkout({paymentSessionId:data.paymentSessionId});return true}catch(e){toast(`Cashfree checkout failed: ${e.message||'error'}`);return false}}
function paymentAmount(order){return order.payment==='card'?Number(order.total):Number(order.advanceRequired||0)}
async function verifyCashfreeReturn(){if(!new URLSearchParams(location.search).has('payment_return'))return;const params=new URLSearchParams(location.search),id=params.get('order_id')||params.get('orderId');if(!id)return;const o=readPendingPayment(id);if(!o){toast('Payment session not found. Please start checkout again.');history.replaceState({},'',location.pathname);return}const endpoint=state.settings.cashfree.verifyEndpoint;if(!endpoint){toast('Cashfree verification endpoint is not configured. Order not confirmed.');return}try{const user=await getCurrentAuthUser();if(!user?.email||!state.profile.emailVerified){toast('Email verification is required before order confirmation.');return}const res=await fetch(`${endpoint}?order_id=${encodeURIComponent(id)}`,{cache:'no-store'});if(!res.ok)throw new Error('verification failed');const data=await res.json();const paid=Boolean(data?.paid||data?.status==='PAID'||data?.order_status==='PAID');if(!paid){toast('Payment is not yet confirmed. Order is not confirmed.');return}const amount=paymentAmount(o);o.status='Placed';o.paymentStatus='paid';o.advancePaid=amount;o.remainingDue=Math.max(0,o.total-amount);o.customer.phone=phoneDigits(o.customer.phone);const cloudSaved=await saveOrderToSupabase(o);if(!cloudSaved){toast('Payment succeeded, but order could not be saved. Please contact support.');return}state.orders.unshift(ensureOrderTracking(o));state.profile=mergeDeep(state.profile,o.customer);state.profile.emailVerified=true;state.profile.authUserId=user.id;state.cart=[];save();clearPendingPayment();history.replaceState({},'',location.pathname);showSuccess(o)}catch(e){toast('Payment verification is pending. Order is not confirmed.')}}
async function renderUPIQR(text,targetId='upiQr'){const el=document.getElementById(targetId);if(!el)return;try{if(!window.QRCode){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/qrcode@1.5.3/build/qrcode.min.js';s.onload=resolve;s.onerror=reject;document.head.appendChild(s)})}const canvas=document.createElement('canvas');await QRCode.toCanvas(canvas,text,{width:200,margin:1});el.innerHTML='';el.appendChild(canvas)}catch{el.innerHTML='<div class="qr-error">QR unavailable — use the UPI button.</div>'}}

function profileGate(){}
function finishProfileGate(){}
function skipProfileGate(){}
function applyTheme(){const t=state.settings.theme||DEFAULT_SETTINGS.theme;document.documentElement.style.setProperty('--pista',t.primary);document.documentElement.style.setProperty('--gold',t.accent);document.documentElement.style.setProperty('--silver',t.silver);document.documentElement.style.setProperty('--ink',t.ink)}
function siteBackground(){const s=state.settings;if(!s.backgroundVideoEnabled||!s.backgroundVideo)return '';return `<div class="site-bg-video"><video autoplay muted loop playsinline src="${esc(s.backgroundVideo)}"></video><div></div></div>`}
function menuPage(){return `<section class="section menu-page"><div class="container"><div class="menu-page-grid"><a href="index.html" class="menu-tile"><span>01</span><b>Home</b><small>Main storefront</small></a><a href="shop.html" class="menu-tile"><span>02</span><b>Shop All</b><small>Browse products</small></a><a href="categories.html" class="menu-tile"><span>03</span><b>Categories</b><small>Collections</small></a><a href="wishlist.html" class="menu-tile"><span>04</span><b>Wishlist</b><small>Saved products</small></a><a href="bag.html" class="menu-tile"><span>05</span><b>Bag</b><small>${totalItems()} item(s)</small></a><a href="customer-details.html" class="menu-tile"><span>06</span><b>Customer Details</b><small>Saved delivery details</small></a><a href="tracking.html" class="menu-tile"><span>07</span><b>Track Order</b><small>Status and ETA</small></a><a href="help-care.html" class="menu-tile"><span>08</span><b>Help & Care</b><small>Support</small></a><a href="reviews.html" class="menu-tile"><span>09</span><b>Reviews</b><small>Customer feedback</small></a><a href="admin.html" class="menu-tile"><span>10</span><b>Admin Panel</b><small>Store controls</small></a></div></div></section>`} function paymentStatusPanel(order){const amount=Number(order.advanceRequired||order.total||0);return `<div class="payment-page-panel"><div class="eyebrow">PAYMENT / ACTION NEEDED</div><h3>${esc(order.id)}</h3><p>${order.payment==='cod'?`Pay ${money(amount)} now. The remaining ${money(order.remainingDue)} is due after delivery.`:'Complete your payment to finish this order.'}</p><div id="pendingQr" class="qr-box"></div><a class="btn primary full" href="${esc(makeUpiLink(order,amount))}">Open UPI App →</a><button class="btn ghost full" onclick="markPaymentVerificationPending('${esc(order.id)}')">I have paid — verify payment</button></div>`} function trackingPage(o,paymentPending){return `<section class="section"><div class="tracking-layout"><div class="checkout-card"><div class="eyebrow">ORDER LOOKUP</div><h2>Track your delivery.</h2><div class="field"><label>ORDER ID *</label><input id="trackId" value="${esc(o?.id||'')}"></div><div class="field"><label>PHONE *</label><input id="trackPhone" value="${esc(o?.customer?.phone||'')}"></div><button class="btn primary full" onclick="trackOrder()">Track Order →</button><div id="trackResult">${o?trackingCard(o):''}</div></div><div class="checkout-card"><h3>Order updates</h3><p class="muted">Status, expected arrival, courier, tracking number and delivery timeline.</p>${o&&paymentPending?paymentStatusPanel(o):''}</div></div></section>`} function pageContent(){const page=document.body.dataset.page||'home';if(page==='home')return `${hero()}${categories()}${shop()}${trust()}`;if(page==='shop')return shop();if(page==='categories'){const params=new URLSearchParams(location.search);if(params.get('view')==='menu')return menuPage();const cat=params.get('category');if(cat&&cat!=='All'){const items=state.products.filter(p=>p.category===cat);return `<section class="section"><div class="container"><div class="section-head"><div><div class="eyebrow">COLLECTION</div><h2>${esc(cat)}</h2></div><a class="text-link" href="categories.html">ALL CATEGORIES →</a></div><div class="product-grid">${items.map(productCard).join('')||'<div class="empty-state">No products in this collection yet.</div>'}</div></div></section>`}return categories();}if(page==='wishlist'){const items=state.products.filter(p=>state.wishlist.includes(p.id));return `<section class="section"><div class="product-grid">${items.length?items.map(productCard).join(''):'<div class="empty-state">Your wishlist is empty.<br><br><a class="btn primary" href="shop.html">Shop Collection →</a></div>'}</div></section>`}if(page==='product'){const p=product(new URLSearchParams(location.search).get('id'));return p?productDetailPage(p):'<div class="empty-state">Product not found.</div>'}if(page==='bag')return bagPage();if(page==='checkout')return checkoutMarkup();if(page==='customer')return customerPage();if(page==='tracking'){const params=new URLSearchParams(location.search);const orderId=params.get('order');const o=orderId?(state.orders.find(x=>x.id===orderId)||null):null;return trackingPage(o,params.get('payment')==='1')}if(page==='support')return supportPage();if(page==='reviews')return reviewsPage();if(page==='search')return searchPage();return `${hero()}${categories()}${shop()}${trust()}`}
function remainingPaymentPercent(method){const pct=method==='upi'?Number(state.settings.upiAdvancePercent||20):method==='cod'?Number(state.settings.codAdvancePercent||20):100;return Math.max(0,100-pct)}
function textOverrideMap(){return state.settings.textOverrides&&typeof state.settings.textOverrides==='object'?state.settings.textOverrides:{}}
function applyTextOverrides(){const map=textOverrideMap();if(!Object.keys(map).length)return;const walker=document.createTreeWalker(document.getElementById('app')||document.body,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){const raw=node.nodeValue||'',trim=raw.trim();if(map[trim])node.nodeValue=raw.replace(trim,String(map[trim]));}}
function reviewSection(p){const rs=state.reviews.filter(r=>r.productId===p.id);return `<section class="product-reviews"><div class="eyebrow">CUSTOMER REVIEWS</div><h2>Reviews.</h2><div class="rating-inline">★ ${p.rating||5} · ${p.reviews||0} reviews</div><div class="review-grid">${rs.length?rs.map(r=>`<article class="review-card"><b>${esc(r.name||'Kryven Customer')}</b><div class="stars">${'★'.repeat(r.rating||5)}${'☆'.repeat(5-(r.rating||5))}</div><p>${esc(r.text||'')}</p></article>`).join(''):'<div class="empty-state small">Verified customer reviews will appear here after delivered orders.</div>'}</div><a class="btn ghost dark-outline" href="reviews.html?product=${encodeURIComponent(p.id)}">View all reviews →</a></section>`}
function productDetailPage(p){const colors=(p.colors||[]).map(colorMeta).filter(x=>x.enabled!==false);const activeSize=Object.entries(p.sizes||{}).find(([s,on])=>on)?.[0]||'';const activeColor=colors[0]?.name||'';window.__selected={id:p.id,size:activeSize,color:activeColor};const recs=state.products.filter(x=>x.id!==p.id).slice(0,4);return `<section class="section product-page-section"><div class="product-detail-grid"><div class="product-visual"><div class="swipe-gallery" aria-label="Product photos" tabindex="0"><div class="swipe-track">${p.images.map((im,i)=>`<div class="swipe-slide"><img src="${esc(im)}" alt="${esc(p.name)} photo ${i+1}" loading="${i?'lazy':'eager'}"></div>`).join('')}</div></div><div class="gallery-dots">${p.images.map((_,i)=>`<span class="gallery-dot ${i===0?'active':''}"></span>`).join('')}<small>Swipe left/right for more photos</small></div></div><div class="product-info product-page-info"><div class="eyebrow">${esc(p.category)} · ${esc(p.id)}</div><h1>${esc(p.name)}</h1><div class="price-row"><b class="price">${money(p.price)}</b><span class="mrp">${money(p.mrp)}</span><span class="discount">${esc(p.discount||'')}</span></div><div class="rating-inline">★ ${p.rating||5} · ${p.reviews||0} reviews</div>${p.offerText?`<div class="product-offer">${esc(p.offerText)}${p.offerUntil?` · Ends ${esc(fmtDay(p.offerUntil))}`:''}</div>`:''}<div class="detail-label">COLOUR</div><div id="colorOptions" class="color-choice">${colors.map((c,i)=>`<button type="button" class="color-option ${i===0?'selected':''}" onclick="selectProductColor('${esc(c.name)}')"><span class="swatch" style="--swatch:${esc(c.hex)}"></span><span>${esc(c.name)}</span></button>`).join('')}</div><div class="detail-label">SIZE</div><div id="sizeOptions" class="opt-row">${Object.entries(p.sizes||{}).map(([sz,on])=>`<button type="button" class="opt ${on?'':'disabled'} ${sz===activeSize?'selected':''}" ${on?`onclick="selectProductSize('${sz}')"`:''}>${sz}${on?'':' · OUT'}</button>`).join('')}</div><div class="size-chart"><div class="panel-title"><h3>Size Chart</h3><span>Approx. garment fit</span></div><div class="size-table"><div><b>Size</b><b>Chest</b><b>Length</b></div><div><span>S</span><span>38–40 in</span><span>27 in</span></div><div><span>M</span><span>40–42 in</span><span>28 in</span></div><div><span>L</span><span>42–44 in</span><span>29 in</span></div><div><span>XL</span><span>44–46 in</span><span>30 in</span></div><div><span>XXL</span><span>46–48 in</span><span>31 in</span></div></div></div><p class="desc">${esc(p.description)}</p><button class="btn primary full" onclick="confirmAdd('${esc(p.id)}')">Add to Bag →</button><button class="btn ghost full dark-outline" onclick="buyNow('${esc(p.id)}')">Buy Now →</button><div class="mini-trust"><span>✓ COD ${Number(state.settings.codAdvancePercent||20)}% now</span><span>✓ UPI</span><span>✓ Card</span></div></div></div><section class="product-description"><div class="eyebrow">PRODUCT DETAILS</div><h2>Description.</h2><p>${esc(p.description)}</p><div class="feature-grid">${(p.features||[]).map(f=>`<div class="feature">✓ ${esc(f)}</div>`).join('')}</div></section>${recs.length?`<section class="product-description"><div class="eyebrow">RECOMMENDED FOR YOU</div><h2>Recommendation.</h2><div class="product-grid recommendation-grid">${recs.map(productCard).join('')}</div></section>`:''}${reviewSection(p)}</section>`}
function bagPage(){if(!state.cart.length)return `<section class="section"><div class="empty-state"><div class="eyebrow">YOUR BAG</div><h2>Nothing here yet.</h2><p>Pick at least one product to continue to checkout.</p><a class="btn primary" href="shop.html">Explore Collection →</a></div></section>`;const sub=cartSubtotal();return `<section class="section"><div class="bag-layout"><div class="bag-list">${state.cart.map((x,i)=>{const p=product(x.id);return `<div class="bag-line"><img src="${esc(x.image||p?.images?.[0]||IMG.hero)}"><div><div class="eyebrow">${esc(p?.category||'')}</div><h3>${esc(p?.name||x.name||x.id)}</h3><p class="muted">${esc(x.color)} · Size ${esc(x.size)}</p><div class="qty"><button onclick="changeQty(${i},-1)">−</button><b>${x.qty}</b><button onclick="changeQty(${i},1)">+</button></div></div><strong>${money((p?.price||0)*x.qty)}</strong></div>`}).join('')}</div><aside class="summary-card"><div class="eyebrow">ORDER SUMMARY</div><h3>Ready when you are.</h3><div class="summary-row"><span>Subtotal</span><b>${money(sub)}</b></div><div class="summary-row"><span>Shipping</span><b>${money(shipping())}</b></div><div class="summary-row total"><span>Total</span><b>${money(sub+shipping())}</b></div><button class="btn primary full" onclick="openCheckout()">Proceed to Checkout →</button></aside></div></section>`}
async function ensureSupabaseScript(){
  if(window.supabase?.createClient) return window.supabase;
  if(window.__kryvenSupabaseScriptPromise) return window.__kryvenSupabaseScriptPromise;
  window.__kryvenSupabaseScriptPromise=new Promise((resolve,reject)=>{
    const existing=document.querySelector('script[data-kryven-supabase]');
    if(existing){existing.addEventListener('load',()=>resolve(window.supabase));existing.addEventListener('error',reject);return}
    const script=document.createElement('script');
    script.dataset.kryvenSupabase='1';
    script.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2';
    script.async=true;
    script.onload=()=>window.supabase?.createClient?resolve(window.supabase):reject(new Error('Supabase Auth library unavailable'));
    script.onerror=()=>reject(new Error('Could not load Supabase Auth library'));
    document.head.appendChild(script);
  });
  return window.__kryvenSupabaseScriptPromise;
}
async function getSupabaseAuthClient(){
  if(window.__kryvenSupabaseAuth)return window.__kryvenSupabaseAuth;
  await ensureSupabaseScript();
  window.__kryvenSupabaseAuth=window.supabase.createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
  return window.__kryvenSupabaseAuth;
}
function normalizePhone(v){
  const digits=String(v||'').replace(/\D/g,'');
  if(digits.length===10)return `+91${digits}`;
  if(digits.length===12&&digits.startsWith('91'))return `+${digits}`;
  if(digits.length===11&&digits.startsWith('0'))return `+91${digits.slice(1)}`;
  return String(v||'').trim();
}
function phoneDigits(v){return normalizePhone(v).replace(/\D/g,'').replace(/^91/,'');}
function validPhone(v){return /^\d{10}$/.test(phoneDigits(v));}
function setFieldError(id,message='Required'){
  const input=document.getElementById(id);if(!input)return;
  const field=input.closest('.field');if(!field)return;
  field.classList.add('field-invalid');
  let err=field.querySelector('.field-error');
  if(!err){err=document.createElement('div');err.className='field-error';field.appendChild(err)}
  err.textContent=message;
}
function clearFieldError(id){
  const input=document.getElementById(id);if(!input)return;
  const field=input.closest('.field');if(!field)return;
  field.classList.remove('field-invalid');
  field.querySelector('.field-error')?.remove();
}
function validateInputValue(id,validator,message){
  const input=document.getElementById(id);if(!input)return true;
  const ok=validator(input.value);if(ok)clearFieldError(id);else setFieldError(id,message);return ok;
}
function wireCheckoutValidation(){
  if(document.body.dataset.page!=='checkout')return;
  const rules={
    coName:[v=>!!v.trim(),'Enter your name'],coPhone:[v=>validPhone(v),'Enter a valid 10-digit phone number'],
    coCity:[v=>!!v.trim(),'Enter your city'],coState:[v=>!!v.trim(),'Enter your state'],
    coPin:[v=>/^\d{6}$/.test(v.trim()),'Enter a valid 6-digit pincode'],coAddress:[v=>!!v.trim(),'Enter your full address'],
    coLandmark:[v=>!!v.trim(),'Enter a landmark'],coEmail:[v=>/^\S+@\S+\.\S+$/.test(v.trim()),'Enter your verified email address']
  };
  Object.entries(rules).forEach(([id,[fn,msg]])=>{const el=document.getElementById(id);if(!el)return;el.addEventListener('input',()=>{if(fn(el.value))clearFieldError(id)});el.addEventListener('blur',()=>validateInputValue(id,fn,msg))});
}
async function getCurrentAuthUser(){try{const client=await getSupabaseAuthClient();const {data:{session}}=await client.auth.getSession();return session?.user||null}catch{return null}}
function startOtpCountdown(){
  clearInterval(window.__otpTimer);let left=60;const btn=document.getElementById('sendOtpBtn');if(btn){btn.disabled=true;btn.textContent=`Resend OTP (${left}s)`}
  window.__otpTimer=setInterval(()=>{left-=1;if(btn)btn.textContent=left>0?`Resend OTP (${left}s)`:'Send OTP';if(left<=0){clearInterval(window.__otpTimer);if(btn)btn.disabled=false}},1000);
}
async function sendEmailOtp(){
  try{
    const input=document.getElementById('pfEmail'),email=input?.value?.trim()||'';
    if(!/^\S+@\S+\.\S+$/.test(email)){setFieldError('pfEmail','Enter a valid email address');toast('Enter a valid email address first');return}
    clearFieldError('pfEmail');
    const client=await getSupabaseAuthClient();
    const {error}=await client.auth.signInWithOtp({email,options:{shouldCreateUser:true}});
    if(error)throw error;
    window.__emailOtp=email;
    const row=document.getElementById('emailOtpRow');if(row)row.hidden=false;
    const status=document.getElementById('emailOtpStatus');if(status)status.textContent=`Verification code sent to ${email}. Enter the 6-digit code.`;
    startEmailOtpCountdown();toast('Verification code sent to your email');
  }catch(error){console.error('sendEmailOtp',error);toast(error.message||'Could not send email verification. Check Supabase Email settings.')}}
function startEmailOtpCountdown(){
  clearInterval(window.__emailOtpTimer);let left=60;const btn=document.getElementById('sendEmailOtpBtn');if(btn){btn.disabled=true;btn.textContent=`Resend code (${left}s)`}
  window.__emailOtpTimer=setInterval(()=>{left-=1;if(btn)btn.textContent=left>0?`Resend code (${left}s)`:'Send verification code';if(left<=0){clearInterval(window.__emailOtpTimer);if(btn)btn.disabled=false}},1000);
}
async function verifyEmailOtp(){
  try{
    const email=(window.__emailOtp||document.getElementById('pfEmail')?.value||'').trim(),otp=(document.getElementById('pfEmailOtp')?.value||'').trim();
    if(!/^\S+@\S+\.\S+$/.test(email)){setFieldError('pfEmail','Enter a valid email address');return}
    if(!/^\d{6}$/.test(otp)){setFieldError('pfEmailOtp','Enter the 6-digit code');toast('Enter the 6-digit verification code');return}
    clearFieldError('pfEmail');clearFieldError('pfEmailOtp');
    const client=await getSupabaseAuthClient();
    const {data,error}=await client.auth.verifyOtp({email,token:otp,type:'email'});
    if(error)throw error;
    const user=data?.user||null;
    state.profile.email=email;state.profile.emailVerified=true;state.profile.authUserId=user?.id||state.profile.authUserId||'';
    save();
    const mark=document.getElementById('emailVerifiedStatus');if(mark){mark.textContent='✓ Email verified';mark.classList.add('verified')}
    const row=document.getElementById('emailOtpRow');if(row)row.hidden=true;clearInterval(window.__emailOtpTimer);
    const btn=document.getElementById('sendEmailOtpBtn');if(btn){btn.disabled=false;btn.textContent='Email Verified'}
    toast('Email verified successfully');
  }catch(error){console.error('verifyEmailOtp',error);setFieldError('pfEmailOtp','Invalid or expired verification code');toast(error.message||'Email verification failed')}}
async function continueWithGoogle(){
  try{
    const client=await getSupabaseAuthClient(),{data:{session}}=await client.auth.getSession(),redirectTo=location.href.split('#')[0].split('?')[0]+'?google_return=1';
    const result=session?.user?await client.auth.linkIdentity({provider:'google',options:{redirectTo}}):await client.auth.signInWithOAuth({provider:'google',options:{redirectTo,queryParams:{access_type:'offline',prompt:'select_account'}}});
    if(result?.error)throw result.error;
  }catch(error){console.error('Google sign-in error',error);toast(error.message||'Google sign-in could not start. Enable Google in Supabase Auth.')}}
async function loadGoogleProfile(){
  try{
    const client=await getSupabaseAuthClient(),{data:{session}}=await client.auth.getSession(),u=session?.user;if(!u)return;
    const meta=u.user_metadata||{},fullName=meta.full_name||meta.name||'',email=u.email||meta.email||'',identities=(u.identities||[]).map(i=>i.provider);
    if(fullName&&!state.profile.name)state.profile.name=fullName;if(email&&!state.profile.email)state.profile.email=email;if(u.email_confirmed_at||email)state.profile.emailVerified=Boolean(u.email_confirmed_at)||state.profile.emailVerified;
    if(u.phone){state.profile.phone=phoneDigits(u.phone);state.profile.phoneVerified=true}
    state.profile.googleConnected=identities.includes('google')||Boolean(state.profile.googleConnected);state.profile.authUserId=u.id;
    if(meta.store_profile&&typeof meta.store_profile==='object'){state.profile=mergeDeep(state.profile,meta.store_profile);if(u.phone){state.profile.phone=phoneDigits(u.phone);state.profile.phoneVerified=true}state.profile.authUserId=u.id}
    save();
    const n=document.getElementById('pfName'),e=document.getElementById('pfEmail'),ph=document.getElementById('pfPhone');if(n&&!n.value)n.value=state.profile.name||'';if(e&&!e.value)e.value=state.profile.email||'';if(ph&&!ph.value&&state.profile.phone)ph.value=state.profile.phone;
    const g=document.getElementById('googleStatus');if(g)g.textContent=state.profile.googleConnected?`Google connected · ${state.profile.email||'account linked'}`:'Name & email can be filled automatically from Google';const ev=document.getElementById('emailVerifiedStatus');if(ev)ev.textContent=state.profile.emailVerified?'✓ Email verified':'Email verification required';
  }catch(error){console.warn('Auth profile restore skipped',error)}}
function collectProfileFrom(prefix='pf'){const p={name:document.getElementById(`${prefix}Name`).value.trim(),phone:document.getElementById(`${prefix}Phone`).value.trim(),email:document.getElementById(`${prefix}Email`).value.trim(),city:document.getElementById(`${prefix}City`).value.trim(),state:document.getElementById(`${prefix}State`).value.trim(),pincode:document.getElementById(`${prefix}Pin`).value.trim(),address:document.getElementById(`${prefix}Address`).value.trim(),landmark:document.getElementById(`${prefix}Landmark`)?.value.trim()||''};p.phone=phoneDigits(p.phone);return p}
async function saveProfile(){
  try{
    const next=collectProfileFrom();
    for(const [id,ok,msg] of [['pfName',!!next.name,'Enter your name'],['pfPhone',validPhone(next.phone),'Enter a valid phone number'],['pfCity',!!next.city,'Enter your city'],['pfState',!!next.state,'Enter your state'],['pfPin',/^\d{6}$/.test(next.pincode),'Enter a valid 6-digit pincode'],['pfAddress',!!next.address,'Enter your address'],['pfLandmark',!!next.landmark,'Enter a landmark']]){if(!ok)setFieldError(id,msg);else clearFieldError(id)}
    if(!next.name||!validPhone(next.phone)||!next.city||!next.state||!/^\d{6}$/.test(next.pincode)||!next.address||!next.landmark){toast('Complete all required fields');return}
    if(next.email&&!/^\S+@\S+\.\S+$/.test(next.email)){setFieldError('pfEmail','Enter a valid email or leave it blank');toast('Check the email address');return}clearFieldError('pfEmail');
    const client=await getSupabaseAuthClient(),{data:{session}}=await client.auth.getSession();if(!session?.user?.email||!state.profile.emailVerified){toast('Verify your email with the code before saving your account.');return}
    
    const merged={...state.profile,...next,emailVerified:true,authUserId:session.user.id};const {error}=await client.auth.updateUser({data:{full_name:next.name,store_profile:merged,email_verified:true}});if(error)throw error;
    const identities=(session.user.identities||[]).map(i=>i.provider);merged.googleConnected=identities.includes('google')||Boolean(merged.googleConnected);state.profile=merged;save();localStorage.setItem(PROFILE_SEEN_KEY,'1');location.href='checkout.html';
  }catch(error){console.error('saveProfile',error);toast(error.message||'Could not save customer profile')}}
function customerPage(){const p=state.profile;return `<section class="section"><div class="checkout-card customer-profile-card"><div class="eyebrow">PROFILE / SECURE ACCOUNT</div><h2>Customer details.</h2><p class="muted">Verify your email once. Your phone number is saved for delivery and order contact. Google can automatically fill your name and Gmail.</p><div class="form-grid"><div class="field"><label>NAME *</label><input id="pfName" value="${esc(p.name)}" required autocomplete="name"></div><div class="field"><label>EMAIL *</label><div class="phone-otp-row"><input id="pfEmail" value="${esc(p.email)}" type="email" required autocomplete="email"><button id="sendEmailOtpBtn" type="button" class="btn" onclick="sendEmailOtp()">${p.emailVerified?'Email Verified':'Send Verification Code'}</button></div><small id="emailVerifiedStatus" class="otp-status ${p.emailVerified?'verified':''}">${p.emailVerified?'✓ Email verified':'Email verification required'}</small></div></div><div id="emailOtpRow" class="otp-row-wrap" hidden><div class="field"><label>EMAIL VERIFICATION CODE *</label><input id="pfEmailOtp" inputmode="numeric" maxlength="6" placeholder="6-digit code" autocomplete="one-time-code"></div><button type="button" class="btn primary" onclick="verifyEmailOtp()">Verify Email</button><div id="emailOtpStatus" class="otp-status">Enter the code sent to your email.</div></div><div class="field" style="margin-top:18px"><label>PHONE NUMBER *</label><input id="pfPhone" value="${esc(p.phone)}" required inputmode="tel" autocomplete="tel" placeholder="10-digit mobile number"></div><button type="button" class="google-signin-btn" onclick="continueWithGoogle()"><span class="google-mark">G</span><span>Continue with Google</span></button><div id="googleStatus" class="google-status">${p.googleConnected?`Google connected · ${esc(p.email||'account linked')}`:'Google will fill your name and Gmail'}</div><div class="form-grid" style="margin-top:18px"><div class="field"><label>CITY *</label><input id="pfCity" value="${esc(p.city)}" required autocomplete="address-level2"></div><div class="field"><label>STATE *</label><input id="pfState" value="${esc(p.state)}" required autocomplete="address-level1"></div><div class="field"><label>PINCODE *</label><input id="pfPin" value="${esc(p.pincode)}" required inputmode="numeric" maxlength="6" pattern="[0-9]{6}" autocomplete="postal-code"></div><div class="field full-span"><label>ADDRESS *</label><textarea id="pfAddress" required autocomplete="street-address">${esc(p.address)}</textarea></div><div class="field full-span"><label>LANDMARK *</label><input id="pfLandmark" value="${esc(p.landmark||'')}" required></div></div><button type="button" class="btn primary" onclick="saveProfile()">Save & Continue →</button><p class="tiny muted" style="margin-top:12px">Email verification is required before checkout. Phone number is saved with your customer details and auto-filled at checkout.</p></div></section>`}

function supportPage(){return `<section class="section"><div class="support-grid"><div class="checkout-card"><div class="eyebrow">HELP & CARE</div><h2>We’re here for your order.</h2><p class="muted">${esc(state.settings.supportText)}</p><a class="btn primary" target="_blank" href="https://wa.me/${esc(state.settings.whatsapp)}?text=${encodeURIComponent('Hello Kryven Era, I need help with my order.')}">Chat on WhatsApp →</a></div><div class="checkout-card"><h3>Payments</h3><p class="muted">COD 20% advance + 80% after delivery, UPI, and card depending on admin settings.</p></div></div></section>`}
function reviewsPage(){return `<section class="section"><div class="review-grid">${state.reviews.length?state.reviews.map(r=>`<article class="review-card"><b>${esc(r.name||'Kryven Customer')}</b><div class="stars">${'★'.repeat(r.rating||5)}${'☆'.repeat(5-(r.rating||5))}</div><p>${esc(r.text||'')}</p></article>`).join(''):'<div class="empty-state">Verified customer reviews appear here after delivery.</div>'}</div></section>`}
function searchPage(){const q=new URLSearchParams(location.search).get('q')||'';const matches=state.products.filter(p=>(p.name+' '+p.category+' '+p.barcode).toLowerCase().includes(q.toLowerCase()));return `<section class="section"><div class="search-page"><div class="search-wrap large"><input class="search" value="${esc(q)}" placeholder="Search" oninput="location.href='search.html?q='+encodeURIComponent(this.value)"></div><div class="product-grid">${matches.map(productCard).join('')||'<div class="empty-state">No matching products found.</div>'}</div></div></section>`}
function render(){applyTheme();const root=document.getElementById('app');if(!root)return;root.innerHTML=siteBackground()+header()+`<main class="${document.body.dataset.page==='home'?'home-main':''}">${document.body.dataset.page==='home'?pageContent():`<div class="container page-shell-title"><div class="page-title"><div class="eyebrow">KRYVEN ERA</div><h1>${esc((document.title||'Kryven Era').replace(/^KRYVEN ERA — /i,'').replace(/^KRYVEN ERA — Wear Your Era$/i,'Store'))}</h1></div>${pageContent()}</div>`}</main>`+footer();applyTextOverrides();if(document.body.dataset.page==='tracking'){const params=new URLSearchParams(location.search);if(params.get('payment')==='1'&&params.get('order'))setTimeout(()=>{const o=state.orders.find(x=>x.id===params.get('order'));if(o)renderUPIQR(makeUpiLink(o,Number(o.advanceRequired||o.total||0)),'pendingQr')},0)}}
function showReferralOnce(){}
function startBarcodeScan(){
  try{if(!('BarcodeDetector' in window)){toast('Barcode scanning is not supported in this browser.');return}const detector=new BarcodeDetector({formats:['ean_13','ean_8','code_128','code_39','upc_a','upc_e']});navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}}).then(async stream=>{const video=document.createElement('video');video.autoplay=true;video.muted=true;video.playsInline=true;video.className='scanner-video';document.body.appendChild(video);video.srcObject=stream;await video.play();const loop=async()=>{try{const codes=await detector.detect(video);if(codes.length){const value=codes[0].rawValue;stream.getTracks().forEach(t=>t.stop());video.remove();const input=document.getElementById('topSearch');if(input)input.value=value;search(value);return}}catch{}requestAnimationFrame(loop)};loop()}).catch(()=>toast('Camera permission denied. Enter the barcode manually.'))}catch{toast('Barcode scanning unavailable.')}}
window.openModal=openModal;window.closeModal=closeModal;window.closeDrawer=closeDrawer;window.openMobileMenu=openMobileMenu;window.openBag=openBag;window.openCheckout=openCheckout;window.openProduct=openProduct;window.openCategory=openCategory;window.toggleWishlist=toggleWishlist;window.openWishlist=openWishlist;window.openProfile=openProfile;window.openSupport=openSupport;window.openTracking=openTracking;window.trackOrder=trackOrder;window.changeQty=changeQty;window.setMainImage=setMainImage;window.selectProductSize=selectProductSize;window.selectProductColor=selectProductColor;window.confirmAdd=id=>{addToBag(id,window.__selected?.size||'',window.__selected?.color||'');location.href='bag.html'};window.buyNow=id=>{addToBag(id,window.__selected?.size||'',window.__selected?.color||'');location.href='checkout.html'};window.applyCheckoutCoupon=applyCheckoutCoupon;window.placeOrder=placeOrder;window.saveProfile=saveProfile;window.sendEmailOtp=sendEmailOtp;window.verifyEmailOtp=verifyEmailOtp;window.search=search;window.renderSearchOverlay=renderSearchOverlay;window.startBarcodeScan=startBarcodeScan;window.skipProfileGate=skipProfileGate;window.finishProfileGate=finishProfileGate;window.markPaymentVerificationPending=markPaymentVerificationPending;window.render=render;window.continueWithGoogle=continueWithGoogle;window.loadGoogleProfile=loadGoogleProfile;

(async function boot(){
  try {
    if('scrollRestoration' in history) history.scrollRestoration='manual';
    window.scrollTo(0,0);
    await verifyCashfreeReturn();
    render();
    await loadGoogleProfile();
    wireCheckoutValidation();
    requestAnimationFrame(()=>window.scrollTo(0,0));

    localStorage.setItem(PROFILE_SEEN_KEY,'1');
  } catch (error) {
    console.error('KRYVEN ERA boot error:', error);
    const root=document.getElementById('app');
    if(root) root.innerHTML='<main style="min-height:100vh;display:grid;place-items:center;padding:24px;background:#eef3e7;font-family:Arial,sans-serif"><div style="max-width:520px;background:#fff;border:1px solid #ddd;border-radius:24px;padding:28px;box-shadow:0 18px 50px rgba(0,0,0,.08)"><h1 style="margin:0 0 10px">KRYVEN ERA</h1><p style="color:#666">The store could not start correctly. Please refresh this page.</p><button onclick="location.reload()" style="padding:12px 18px;border:0;border-radius:12px;background:#d7ad59;font-weight:700">Refresh Store</button></div></main>';
  }
})();
